-- calc_framing_invariants_is_critical
-- Field: FramingInvariants.IsCritical
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_framing_invariants_is_critical(p_invariant_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(severity, '') FROM framing_invariants WHERE invariant_id = p_invariant_id) = 'critical')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_framing_invariants_critical_flag
-- Field: FramingInvariants.CriticalFlag
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_framing_invariants_critical_flag(p_invariant_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN (SELECT NULLIF(severity, '') FROM framing_invariants WHERE invariant_id = p_invariant_id) = 'critical' THEN (1)::text ELSE (0)::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_framing_invariants_is_active_critical
-- Field: FramingInvariants.IsActiveCritical
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_framing_invariants_is_active_critical(p_invariant_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_framing_invariants_is_critical(p_invariant_id) AND (SELECT NULLIF(status, '') FROM framing_invariants WHERE invariant_id = p_invariant_id) = 'active'))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_framing_invariants_is_enforceable
-- Field: FramingInvariants.IsEnforceable
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_framing_invariants_is_enforceable(p_invariant_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_framing_invariants_is_active_critical(p_invariant_id) AND (COALESCE(calc_framing_invariants_axiom_is_active(p_invariant_id), FALSE) = 'true')))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_framing_invariants_enforcement_state
-- Field: FramingInvariants.EnforcementState
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_framing_invariants_enforcement_state(p_invariant_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_framing_invariants_is_enforceable(p_invariant_id) THEN ('enforced')::text ELSE (CASE WHEN (COALESCE(calc_framing_invariants_axiom_is_load_bearing(p_invariant_id), FALSE) = 'true') THEN ('advisory')::text ELSE ('orphan')::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_framing_invariants_needs_attention
-- Field: FramingInvariants.NeedsAttention
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_framing_invariants_needs_attention(p_invariant_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (calc_framing_invariants_enforcement_state(p_invariant_id) = 'orphan')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_platform_features_axiom_short_name
-- Field: PlatformFeatures.AxiomShortName
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: ShortName from related OntologyAxioms


CREATE OR REPLACE FUNCTION calc_platform_features_axiom_short_name(p_feature_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT short_name::text FROM ontology_axioms WHERE axiom_id = (SELECT related_axiom_id FROM platform_features WHERE feature_id = p_feature_id));
$$ LANGUAGE sql STABLE;

-- calc_platform_features_axiom_invariant_count
-- Field: PlatformFeatures.AxiomInvariantCount
-- Type: lookup | DataType: number | Returns: NUMERIC
-- Lookup: InvariantCount from related OntologyAxioms


CREATE OR REPLACE FUNCTION calc_platform_features_axiom_invariant_count(p_feature_id TEXT)
RETURNS NUMERIC AS $$
  SELECT calc_ontology_axioms_invariant_count((SELECT related_axiom_id FROM platform_features WHERE feature_id = p_feature_id));
$$ LANGUAGE sql STABLE;

-- calc_platform_features_axiom_is_load_bearing
-- Field: PlatformFeatures.AxiomIsLoadBearing
-- Type: lookup | DataType: boolean | Returns: BOOLEAN
-- Lookup: IsLoadBearing from related OntologyAxioms


CREATE OR REPLACE FUNCTION calc_platform_features_axiom_is_load_bearing(p_feature_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT calc_ontology_axioms_is_load_bearing((SELECT related_axiom_id FROM platform_features WHERE feature_id = p_feature_id));
$$ LANGUAGE sql STABLE;

-- calc_platform_features_is_readme_stub
-- Field: PlatformFeatures.IsReadmeStub
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_platform_features_is_readme_stub(p_feature_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT readme_length FROM platform_features WHERE feature_id = p_feature_id), 0))::NUMERIC < 400)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_platform_features_is_headline
-- Field: PlatformFeatures.IsHeadline
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_platform_features_is_headline(p_feature_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(tier, '') FROM platform_features WHERE feature_id = p_feature_id) = 'headline')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_platform_features_is_shipped
-- Field: PlatformFeatures.IsShipped
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_platform_features_is_shipped(p_feature_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(status, '') FROM platform_features WHERE feature_id = p_feature_id) = 'shipped')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_platform_features_shipped_flag
-- Field: PlatformFeatures.ShippedFlag
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_platform_features_shipped_flag(p_feature_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN (SELECT NULLIF(status, '') FROM platform_features WHERE feature_id = p_feature_id) = 'shipped' THEN (1)::text ELSE (0)::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_platform_features_needs_readme_work
-- Field: PlatformFeatures.NeedsReadmeWork
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_platform_features_needs_readme_work(p_feature_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_platform_features_is_shipped(p_feature_id) AND calc_platform_features_is_readme_stub(p_feature_id)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_platform_features_is_headline_gap
-- Field: PlatformFeatures.IsHeadlineGap
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_platform_features_is_headline_gap(p_feature_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_platform_features_is_headline(p_feature_id) AND calc_platform_features_needs_readme_work(p_feature_id)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_platform_features_doc_state
-- Field: PlatformFeatures.DocState
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_platform_features_doc_state(p_feature_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_platform_features_is_headline_gap(p_feature_id) THEN ('headline-gap')::text ELSE (CASE WHEN calc_platform_features_needs_readme_work(p_feature_id) THEN ('gap')::text ELSE (CASE WHEN calc_platform_features_is_shipped(p_feature_id) THEN ('documented')::text ELSE ('pending')::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_platform_features_is_axiom_backed
-- Field: PlatformFeatures.IsAxiomBacked
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_platform_features_is_axiom_backed(p_feature_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (((COALESCE(calc_platform_features_axiom_is_load_bearing(p_feature_id), FALSE) = 'true') AND calc_platform_features_is_shipped(p_feature_id)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_platform_features_is_showcase_feature
-- Field: PlatformFeatures.IsShowcaseFeature
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_platform_features_is_showcase_feature(p_feature_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_platform_features_is_axiom_backed(p_feature_id) AND calc_platform_features_doc_state(p_feature_id) = 'documented'))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_rulebook_source_spokes_is_bidirectional
-- Field: RulebookSourceSpokes.IsBidirectional
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_rulebook_source_spokes_is_bidirectional(p_spoke_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(direction, '') FROM rulebook_source_spokes WHERE spoke_id = p_spoke_id) = 'bidirectional')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_rulebook_source_spokes_is_optional
-- Field: RulebookSourceSpokes.IsOptional
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_rulebook_source_spokes_is_optional(p_spoke_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (NOT (COALESCE((SELECT required FROM rulebook_source_spokes WHERE spoke_id = p_spoke_id), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_rulebook_source_spokes_is_optional_bidirectional
-- Field: RulebookSourceSpokes.IsOptionalBidirectional
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_rulebook_source_spokes_is_optional_bidirectional(p_spoke_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_rulebook_source_spokes_is_optional(p_spoke_id) AND calc_rulebook_source_spokes_is_bidirectional(p_spoke_id)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_rulebook_source_spokes_spoke_kind
-- Field: RulebookSourceSpokes.SpokeKind
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_rulebook_source_spokes_spoke_kind(p_spoke_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_rulebook_source_spokes_is_optional_bidirectional(p_spoke_id) THEN ('editing-surface')::text ELSE (CASE WHEN calc_rulebook_source_spokes_is_bidirectional(p_spoke_id) THEN ('required-sync')::text ELSE ('one-way')::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_rulebook_source_spokes_is_advertised_surface
-- Field: RulebookSourceSpokes.IsAdvertisedSurface
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_rulebook_source_spokes_is_advertised_surface(p_spoke_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_rulebook_source_spokes_spoke_kind(p_spoke_id) = 'editing-surface' AND NOT (COALESCE((SELECT required FROM rulebook_source_spokes WHERE spoke_id = p_spoke_id), FALSE))))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_rulebook_source_spokes_surface_label
-- Field: RulebookSourceSpokes.SurfaceLabel
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_rulebook_source_spokes_surface_label(p_spoke_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_rulebook_source_spokes_is_advertised_surface(p_spoke_id) THEN (CONCAT((SELECT NULLIF(name, '') FROM rulebook_source_spokes WHERE spoke_id = p_spoke_id), ' (optional surface)'))::text ELSE ((SELECT NULLIF(name, '') FROM rulebook_source_spokes WHERE spoke_id = p_spoke_id))::text END)::text;
$$ LANGUAGE sql STABLE;

