-- Field: RulebookFlavors.DomainFindingCount
-- Type: lookup | DataType: number | Returns: NUMERIC
-- Lookup: FindingCount from related RulebookDomains


CREATE OR REPLACE FUNCTION calc_rulebook_flavors_domain_finding_count(p_flavor_id TEXT)
