  SELECT (CONCAT((SELECT NULLIF(narrative_name, '') FROM demo_narratives WHERE narrative_id = p_narrative_id), ' / ', (SELECT NULLIF(step_name, '') FROM demo_narratives WHERE narrative_id = p_narrative_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_demo_narratives_is_deprecated
-- Field: DemoNarratives.IsDeprecated
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_demo_narratives_is_deprecated(p_narrative_id TEXT)
