-- calc_flavor_tags_flavor_tag_count
-- Field: FlavorTags.FlavorTagCount
-- Type: lookup | DataType: number | Returns: NUMERIC
-- Lookup: TagCount from related RulebookFlavors


CREATE OR REPLACE FUNCTION calc_flavor_tags_flavor_tag_count(p_flavor_tag_id TEXT)
RETURNS NUMERIC AS $$
  SELECT calc_rulebook_flavors_tag_count((SELECT flavor FROM flavor_tags WHERE flavor_tag_id = p_flavor_tag_id));
$$ LANGUAGE sql STABLE;

-- get_rulebook_tags_label
