CREATE OR REPLACE FUNCTION get_rulebook_tags_label(p_tag_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT label FROM rulebook_tags WHERE tag_id = p_tag_id);
$$ LANGUAGE sql STABLE;

-- get_rulebook_tags_category
-- Helper function: Get Category from RulebookTags by TagId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_rulebook_tags_category(p_tag_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT category FROM rulebook_tags WHERE tag_id = p_tag_id);
$$ LANGUAGE sql STABLE;

-- get_rulebook_tags_color
-- Helper function: Get Color from RulebookTags by TagId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_rulebook_tags_color(p_tag_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT color FROM rulebook_tags WHERE tag_id = p_tag_id);
$$ LANGUAGE sql STABLE;

-- get_rulebook_tags_emoji
-- Helper function: Get Emoji from RulebookTags by TagId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_rulebook_tags_emoji(p_tag_id TEXT)
