-- calc_build_phases_is_priced
-- Field: BuildPhases.IsPriced
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_build_phases_is_priced(p_build_phase_id TEXT)
RETURNS BOOLEAN AS $$
