CREATE OR REPLACE FUNCTION calc_skill_routes_from_status(p_skill_route_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT status::text FROM claude_skills WHERE skill_id = (SELECT from_skill FROM skill_routes WHERE skill_route_id = p_skill_route_id));
$$ LANGUAGE sql STABLE;

-- calc_skill_routes_to_status
-- Field: SkillRoutes.ToStatus
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: Status from related ClaudeSkills


CREATE OR REPLACE FUNCTION calc_skill_routes_to_status(p_skill_route_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT status::text FROM claude_skills WHERE skill_id = (SELECT to_skill FROM skill_routes WHERE skill_route_id = p_skill_route_id));
$$ LANGUAGE sql STABLE;

-- calc_skill_routes_to_inbound_count
-- Field: SkillRoutes.ToInboundCount
-- Type: lookup | DataType: number | Returns: NUMERIC
-- Lookup: InboundRouteCount from related ClaudeSkills


CREATE OR REPLACE FUNCTION calc_skill_routes_to_inbound_count(p_skill_route_id TEXT)
RETURNS NUMERIC AS $$
  SELECT calc_claude_skills_inbound_route_count((SELECT to_skill FROM skill_routes WHERE skill_route_id = p_skill_route_id));
$$ LANGUAGE sql STABLE;

-- calc_skill_routes_from_outbound_count
-- Field: SkillRoutes.FromOutboundCount
-- Type: lookup | DataType: number | Returns: NUMERIC
-- Lookup: OutboundRouteCount from related ClaudeSkills


CREATE OR REPLACE FUNCTION calc_skill_routes_from_outbound_count(p_skill_route_id TEXT)
RETURNS NUMERIC AS $$
  SELECT calc_claude_skills_outbound_route_count((SELECT from_skill FROM skill_routes WHERE skill_route_id = p_skill_route_id));
$$ LANGUAGE sql STABLE;

-- calc_skill_routes_name
-- Field: SkillRoutes.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_skill_routes_name(p_skill_route_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(from_skill, '') FROM skill_routes WHERE skill_route_id = p_skill_route_id), ' -> ', (SELECT NULLIF(to_skill, '') FROM skill_routes WHERE skill_route_id = p_skill_route_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_skill_routes_is_orchestrator_route
-- Field: SkillRoutes.IsOrchestratorRoute
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_skill_routes_is_orchestrator_route(p_skill_route_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(from_skill, '') FROM skill_routes WHERE skill_route_id = p_skill_route_id) = 'effortless-orchestrator')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_skill_routes_is_deprecated_target
-- Field: SkillRoutes.IsDeprecatedTarget
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_skill_routes_is_deprecated_target(p_skill_route_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (calc_skill_routes_to_status(p_skill_route_id) = 'deprecated')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_skill_routes_is_hub_edge
-- Field: SkillRoutes.IsHubEdge
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_skill_routes_is_hub_edge(p_skill_route_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_skill_routes_from_outbound_count(p_skill_route_id), 0))::NUMERIC >= 5)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_skill_routes_is_into_leaf
-- Field: SkillRoutes.IsIntoLeaf
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_skill_routes_is_into_leaf(p_skill_route_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(calc_skill_routes_to_inbound_count(p_skill_route_id), 0))::NUMERIC = 1)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_skill_routes_is_stale
-- Field: SkillRoutes.IsStale
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_skill_routes_is_stale(p_skill_route_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_skill_routes_is_deprecated_target(p_skill_route_id) OR calc_skill_routes_from_status(p_skill_route_id) = 'deprecated'))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_skill_routes_edge_class
-- Field: SkillRoutes.EdgeClass
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_skill_routes_edge_class(p_skill_route_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_skill_routes_is_stale(p_skill_route_id) THEN ('stale')::text ELSE (CASE WHEN calc_skill_routes_is_hub_edge(p_skill_route_id) THEN (CASE WHEN calc_skill_routes_is_into_leaf(p_skill_route_id) THEN ('hub-to-leaf')::text ELSE ('hub-fanout')::text END)::text ELSE ('peer')::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_skill_routes_route_label
-- Field: SkillRoutes.RouteLabel
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_skill_routes_route_label(p_skill_route_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(from_skill, '') FROM skill_routes WHERE skill_route_id = p_skill_route_id), ' -> ', (SELECT NULLIF(to_skill, '') FROM skill_routes WHERE skill_route_id = p_skill_route_id), ' [', calc_skill_routes_edge_class(p_skill_route_id), ']'))::text;
$$ LANGUAGE sql STABLE;

