-- Field: ProjectSlotWitnesses.RequiredPresentFlag
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_project_slot_witnesses_required_present_flag(p_project_slot_witness_id TEXT)
RETURNS NUMERIC AS $$
